python3 -c "
import json
import os
# Search for any 'key_reviewer' or 'reviewer' mentions across all data
for f in sorted(os.listdir('DATA/products')):
    with open(f'DATA/products/{f}') as fp:
        d = json.load(fp)
    text = json.dumps(d).lower()
    if 'key_reviewer' in text or 'key reviewer' in text:
        print(f'{f}: contains key_reviewer')
    if 'reviewer' in text and 'reviewed_by' not in text:
        # Find context
        idx = text.find('reviewer')
        while idx != -1:
            context = text[max(0,idx-100):idx+200]
            if 'reviewer' in context:
                print(f'  {f}: ...{context}...')
                idx = text.find('reviewer', idx+1)
                if idx > 1000000:
                    break
            else:
                break
" 2>&1 | head -50

